public class LibraryActivity extends MenuActivity {
    private static final int PICK_FOLDER=42,PICK_COVER=43;
    private CoverArt covers;private Uri coverTarget;
    private final ExecutorService scanner=Executors.newSingleThreadExecutor();
    private final ArrayList<Entry> entries=new ArrayList<>(),visible=new ArrayList<>();
    private android.content.SharedPreferences prefs;
    private GamesAdapter adapter;private TextView status,count,empty;private EditText search;private GridView grid;
    private final java.util.Map<String,Button> navigation=new java.util.LinkedHashMap<>();
    private Button settingsButton;
    private int sidebarPosition,lastGamePosition;
    private boolean compact;
    private volatile int generation;private String section="All games";private Entry pending;
    private record Entry(String name,Uri uri,long size){}
    private static String title(String name){return name.replaceFirst("(?i)\\.(chd|iso|bin|img|exe)$","").replaceAll("(?i)\\s*\\((USA|Europe|Japan|World|Rev[^)]*)\\)","").replaceAll("\\s*\\[[^]]*\\]","").trim();}
    @Override public void onCreate(Bundle state){super.onCreate(state);Ui.chrome(this);covers=new CoverArt(this);if(state!=null && state.getString("coverTarget")!=null)coverTarget=Uri.parse(state.getString("coverTarget"));prefs=getSharedPreferences("LibraryActivity",0);compact=getResources().getConfiguration().screenWidthDp<600;
        LinearLayout root=new LinearLayout(this);root.setBackgroundColor(Ui.BG);
        LinearLayout nav=new LinearLayout(this);nav.setOrientation(1);nav.setPadding(Ui.dp(this,compact?8:20),Ui.dp(this,22),Ui.dp(this,compact?8:16),Ui.dp(this,16));nav.setBackgroundColor(0xff111722);
        TextView brand=Ui.heading(this,compact?"PSX":"PSX LAB",compact?16:23);brand.setTextColor(Ui.ACCENT);nav.addView(brand);TextView sub=Ui.text(this,"PLAYSTATION EMULATOR",9,Ui.MUTED);sub.setLetterSpacing(.12f);nav.addView(sub);if(compact)sub.setVisibility(View.GONE);Ui.gap(nav,30);
        for(String item:new String[]{"All games","Recently played","Favorites"}){Button b=Ui.outlineButton(this,compact?(item.equals("All games")?"Games":item.equals("Favorites")?"★":"Recent"):item,false);b.setContentDescription(item);navigation.put(item,b);if(compact){b.setPadding(0,0,0,0);b.setTextSize(11);}nav.addView(b,new LinearLayout.LayoutParams(-1,Ui.dp(this,44)));if(!item.equals("Favorites"))Ui.gap(nav,8);b.setOnClickListener(v->{section=item;filter();});}
        Button settings=Ui.outlineButton(this,compact?"⚙":"Settings",false);settingsButton=settings;settings.setContentDescription("Settings");settings.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));nav.addView(settings,new LinearLayout.LayoutParams(-1,Ui.dp(this,44)));
        View spacer=new View(this);nav.addView(spacer,new LinearLayout.LayoutParams(1,0,1));
        TextView footer=Ui.text(this,Ui.version(this)+(compact?"":"  ·  Original engine"),10,Ui.MUTED);footer.setPadding(0,Ui.dp(this,14),0,0);nav.addView(footer);
        root.addView(nav,new LinearLayout.LayoutParams(Ui.dp(this,compact?72:182),-1));
        LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.setPadding(Ui.dp(this,compact?14:24),Ui.dp(this,18),Ui.dp(this,compact?14:24),0);
        LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);LinearLayout headings=new LinearLayout(this);headings.setOrientation(1);count=Ui.heading(this,"Your library",26);headings.addView(count);status=Ui.text(this,"Loading games…",12,Ui.MUTED);headings.addView(status);top.addView(headings,new LinearLayout.LayoutParams(0,-2,1));
        Button refresh=Ui.button(this,"↻",false);refresh.setContentDescription("Rescan games folder");refresh.setOnClickListener(v->scan());top.addView(refresh,new LinearLayout.LayoutParams(Ui.dp(this,44),Ui.dp(this,42)));
        Button choose=Ui.button(this,compact?"+":"+ Add folder",true);choose.setContentDescription("Add games folder");choose.setOnClickListener(v->pick());LinearLayout.LayoutParams add=new LinearLayout.LayoutParams(-2,Ui.dp(this,42));add.leftMargin=Ui.dp(this,10);top.addView(choose,add);content.addView(top);Ui.gap(content,16);
        search=new EditText(this);search.setSingleLine(true);search.setHint("Search games");search.setTextColor(Ui.TEXT);search.setHintTextColor(Ui.MUTED);search.setTextSize(14);search.setPadding(Ui.dp(this,16),0,Ui.dp(this,16),0);search.setBackground(Ui.box(Ui.PANEL,10,this));content.addView(search,new LinearLayout.LayoutParams(-1,Ui.dp(this,42)));Ui.gap(content,16);
        FrameLayout body=new FrameLayout(this);grid=new GridView(this);grid.setNumColumns(GridView.AUTO_FIT);grid.setColumnWidth(Ui.dp(this,140));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);grid.setHorizontalSpacing(Ui.dp(this,12));grid.setVerticalSpacing(Ui.dp(this,12));grid.setPadding(0,0,0,Ui.dp(this,16));grid.setClipToPadding(false);adapter=new GamesAdapter();grid.setAdapter(adapter);grid.setOnItemClickListener((p,v,position,id)->launch(visible.get(position)));grid.setOnItemLongClickListener((p,v,position,id)->{options(visible.get(position));return true;});body.addView(grid,new FrameLayout.LayoutParams(-1,-1));
        empty=Ui.text(this,"",16,Ui.MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(20,20,20,20);body.addView(empty,new FrameLayout.LayoutParams(-1,-1));empty.setVisibility(View.GONE);content.addView(body,new LinearLayout.LayoutParams(-1,0,1));root.addView(content,new LinearLayout.LayoutParams(0,-1,1));setContentView(root);
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){filter();}public void afterTextChanged(Editable e){}});scan();
    }
    @Override protected void onResume(){super.onResume();if(covers!=null)covers.resume();if(adapter!=null)filter();if(pending!=null && new java.io.File(getFilesDir(),"bios.bin").isFile()){Entry e=pending;pending=null;launch(e);}}
    @Override protected void onStop(){if(covers!=null)covers.pause();super.onStop();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(coverTarget!=null)state.putString("coverTarget",coverTarget.toString());}
    private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);try{startActivityForResult(i,PICK_FOLDER);}catch(ActivityNotFoundException e){status.setText("Android folder picker is unavailable.");}}
    @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK_COVER){Uri target=coverTarget;coverTarget=null;if(result==RESULT_OK && target!=null && data!=null && data.getData()!=null)covers.importImage(target,data.getData(),ok->{if(isDestroyed())return;adapter.notifyDataSetChanged();Toast.makeText(this,ok?"Box art saved":"Could not open that image",Toast.LENGTH_SHORT).show();});return;}if(request!=PICK_FOLDER || result!=RESULT_OK || data==null || data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);String old=prefs.getString("tree",null);prefs.edit().putString("tree",uri.toString()).apply();if(old!=null && !old.equals(uri.toString()))try{getContentResolver().releasePersistableUriPermission(Uri.parse(old),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}scan();}catch(SecurityException e){status.setText("Folder access could not be saved. Choose the folder again.");}}
    private void scan(){int token=++generation;entries.clear();filter();String saved=prefs.getString("tree",null);if(saved==null){status.setText("Add a folder to get started");empty.setText("Your games, ready to play\n\nAdd a folder containing CHD, ISO, BIN, IMG or PS-X EXE files.");return;}status.setText("Scanning your games…");scanner.execute(()->{ArrayList<Entry> found=new ArrayList<>();try{Uri tree=Uri.parse(saved);ArrayDeque<String> dirs=new ArrayDeque<>();Set<String> visited=new HashSet<>();dirs.add(DocumentsContract.getTreeDocumentId(tree));int seen=0;while(!dirs.isEmpty()){if(token!=generation || Thread.currentThread().isInterrupted())return;String dir=dirs.removeFirst();if(!visited.add(dir))continue;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,dir);try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE},null,null,null)){if(c==null)throw new IllegalStateException("Folder unavailable");while(c.moveToNext()){if(token!=generation)return;if(++seen>20000)throw new IllegalStateException("Choose a smaller games folder (under 20,000 files)");String id=c.getString(0),name=c.getString(1),mime=c.getString(2);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime))dirs.add(id);else if(name!=null && name.toLowerCase(Locale.ROOT).matches(".*\\.(iso|bin|chd|exe|img)$"))found.add(new Entry(name,DocumentsContract.buildDocumentUriUsingTree(tree,id),c.isNull(3)?-1:c.getLong(3)));}}}found.sort(Comparator.comparing(e->title(e.name).toLowerCase(Locale.ROOT)));runOnUiThread(()->{if(token!=generation)return;entries.addAll(found);filter();});}catch(Exception e){runOnUiThread(()->{if(token==generation){status.setText("Folder unavailable");empty.setVisibility(View.VISIBLE);empty.setText(e.getMessage()+"\n\nUse Add folder to restore access.");}});}});}
    private void filter(){if(adapter==null)return;for(java.util.Map.Entry<String,Button> item:navigation.entrySet())Ui.selectOutline(item.getValue(),item.getKey().equals(section));visible.clear();String query=search==null?"":search.getText().toString().trim().toLowerCase(Locale.ROOT);Set<String> favorites=prefs.getStringSet("favorites",Collections.emptySet());for(Entry e:entries){if(!title(e.name).toLowerCase(Locale.ROOT).contains(query))continue;if(section.equals("Favorites") && !favorites.contains(e.uri.toString()))continue;if(section.equals("Recently played") && prefs.getLong("last_"+e.uri,0)==0)continue;visible.add(e);}if(section.equals("Recently played"))visible.sort((a,b)->Long.compare(prefs.getLong("last_"+b.uri,0),prefs.getLong("last_"+a.uri,0)));count.setText(section.equals("All games")?"Your library":section);status.setText(entries.size()+" games  ·  "+(new java.io.File(getFilesDir(),"bios.bin").isFile()?"BIOS ready":"BIOS setup needed"));empty.setVisibility(visible.isEmpty()?View.VISIBLE:View.GONE);empty.setText(entries.isEmpty()?"Your games, ready to play\n\nAdd a folder to build your library.":query.isEmpty()?(section.equals("Favorites")?"No favorites yet\n\nHold a game to add it to your favorites.":"No games played yet"):"No games match “"+search.getText()+"”");adapter.notifyDataSetChanged();}
    private void launch(Entry e){if(!e.name.toLowerCase(Locale.ROOT).endsWith(".exe") && !new java.io.File(getFilesDir(),"bios.bin").isFile()){new AlertDialog.Builder(this).setTitle("Choose a PlayStation BIOS").setMessage("Import your 512 KiB BIOS dump once to launch disc games.").setPositiveButton("Choose BIOS",(d,w)->{pending=e;startActivity(new Intent(this,BiosActivity.class));}).setNegativeButton("Cancel",null).show();return;}prefs.edit().putLong("last_"+e.uri,System.currentTimeMillis()).apply();startActivity(new Intent(this,BootActivity.class).putExtra("uri",e.uri.toString()).putExtra("name",e.name));}
    private void options(Entry e){Set<String> fav=new HashSet<>(prefs.getStringSet("favorites",Collections.emptySet()));boolean saved=fav.contains(e.uri.toString());new AlertDialog.Builder(this).setTitle(title(e.name)).setItems(new String[]{"Play",saved?"Remove favorite":"Add to favorites","Choose box art","Find box art again","File information"},(d,which)->{
        if(which==0)launch(e);
        else if(which==1){if(saved)fav.remove(e.uri.toString());else fav.add(e.uri.toString());prefs.edit().putStringSet("favorites",fav).apply();filter();}
        else if(which==2){coverTarget=e.uri;Intent image=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(image,PICK_COVER);}catch(ActivityNotFoundException ex){Toast.makeText(this,"Image picker unavailable",Toast.LENGTH_SHORT).show();}}
        else if(which==3){covers.retry(e.uri);adapter.notifyDataSetChanged();}
        else new AlertDialog.Builder(this).setTitle("File information").setMessage(e.name+"\n\n"+(e.size<0?"Unknown size":String.format(Locale.ROOT,"%.1f MB",e.size/1048576d))).setPositiveButton("Done",null).show();}).show();}
    @Override public boolean onKeyDown(int code,KeyEvent event){if(code==KeyEvent.KEYCODE_BUTTON_A && grid.hasFocus()){int at=grid.getSelectedItemPosition();if(at>=0 && at<visible.size())launch(visible.get(at));return true;}return super.onKeyDown(code,event);}
    @Override protected boolean navigateMenuDirection(KeyEvent event){
        ArrayList<Button> sidebar=new ArrayList<>(navigation.values());sidebar.add(settingsButton);
        int code=event.getKeyCode();View focused=getCurrentFocus();int at=sidebar.indexOf(focused);
        if(at>=0){
            if(code==KeyEvent.KEYCODE_DPAD_UP||code==KeyEvent.KEYCODE_DPAD_DOWN){if(event.getAction()==KeyEvent.ACTION_DOWN){sidebarPosition=Math.max(0,Math.min(sidebar.size()-1,at+(code==KeyEvent.KEYCODE_DPAD_DOWN?1:-1)));sidebar.get(sidebarPosition).requestFocusFromTouch();}return true;}
            if(code==KeyEvent.KEYCODE_DPAD_LEFT)return true;
            if(code==KeyEvent.KEYCODE_DPAD_RIGHT){if(event.getAction()==KeyEvent.ACTION_DOWN){sidebarPosition=at;if(grid.getCount()>0){grid.requestFocusFromTouch();grid.setSelection(Math.min(lastGamePosition,grid.getCount()-1));}else search.requestFocusFromTouch();}return true;}
        }
        if(grid.hasFocus()&&code==KeyEvent.KEYCODE_DPAD_LEFT){int selected=grid.getSelectedItemPosition();int columns=Math.max(1,grid.getNumColumns());if(selected<0||selected%columns==0){if(event.getAction()==KeyEvent.ACTION_DOWN){lastGamePosition=Math.max(0,selected);sidebar.get(sidebarPosition).requestFocusFromTouch();}return true;}}
        return false;
    }
    @Override protected void onDestroy(){generation++;scanner.shutdownNow();if(covers!=null)covers.close();super.onDestroy();}
    private final class GamesAdapter extends BaseAdapter{
        public int getCount(){return visible.size();}public Object getItem(int p){return visible.get(p);}public long getItemId(int p){return p;}
        public View getView(int position,View old,android.view.ViewGroup parent){
            Entry e=visible.get(position);LinearLayout card;Tile tile;
            if(old instanceof LinearLayout && old.getTag() instanceof Tile){card=(LinearLayout)old;tile=(Tile)old.getTag();}
            else{card=new LinearLayout(LibraryActivity.this);card.setOrientation(1);int pad=Ui.dp(LibraryActivity.this,8);card.setPadding(pad,pad,pad,pad);android.graphics.drawable.StateListDrawable bg=new android.graphics.drawable.StateListDrawable();bg.addState(new int[]{android.R.attr.state_pressed},Ui.box(0xff27433f,12,LibraryActivity.this));bg.addState(new int[]{android.R.attr.state_selected},Ui.box(0xff27433f,12,LibraryActivity.this));bg.addState(new int[]{},Ui.box(Ui.PANEL,12,LibraryActivity.this));card.setBackground(bg);
                Cover cover=new Cover();card.addView(cover,new LinearLayout.LayoutParams(-1,-2));TextView name=Ui.heading(LibraryActivity.this,"",13);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(0,Ui.dp(LibraryActivity.this,7),0,0);card.addView(name,new LinearLayout.LayoutParams(-1,Ui.dp(LibraryActivity.this,40)));TextView detail=Ui.text(LibraryActivity.this,"",10,Ui.MUTED);card.addView(detail);tile=new Tile(cover,name,detail);card.setTag(tile);
            }
            tile.cover.bind(e);tile.name.setText(title(e.name));String ext=e.name.substring(e.name.lastIndexOf('.')+1).toUpperCase(Locale.ROOT);boolean favorite=prefs.getStringSet("favorites",Collections.emptySet()).contains(e.uri.toString());tile.detail.setText(ext+(favorite?"   ★":"")+"   ·   "+(e.size<0?"":String.format(Locale.ROOT,"%.0f MB",e.size/1048576d)));card.setContentDescription(title(e.name)+", "+ext+", play");return card;
        }
    }
    private final class Tile{final Cover cover;final TextView name,detail;Tile(Cover c,TextView n,TextView d){cover=c;name=n;detail=d;}}
    private final class Cover extends ImageView{private Entry entry;private String bound;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);Cover(){super(LibraryActivity.this);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);setScaleType(ScaleType.FIT_CENTER);setBackground(Ui.box(0xff0a0e15,7,LibraryActivity.this));setClipToOutline(true);}
        void bind(Entry e){entry=e;bound=e.uri.toString();setImageDrawable(null);String requested=bound;covers.load(e.name,e.uri,bitmap->{if(requested.equals(bound) && bitmap!=null)setImageBitmap(bitmap);});}
        @Override protected void onMeasure(int width,int height){super.onMeasure(width,height);setMeasuredDimension(getMeasuredWidth(),getMeasuredWidth());}
        @Override public void onDraw(Canvas c){if(getDrawable()!=null){super.onDraw(c);return;}if(entry==null)return;int hash=entry.name.hashCode();int[] colors={0xff285e61,0xff3b4776,0xff615035,0xff5e3d61,0xff365664};int color=colors[Math.floorMod(hash,colors.length)];paint.setShader(new LinearGradient(0,0,getWidth(),getHeight(),color,0xff192333,Shader.TileMode.CLAMP));c.drawRoundRect(0,0,getWidth(),getHeight(),Ui.dp(getContext(),7),Ui.dp(getContext(),7),paint);paint.setShader(null);paint.setColor(0x20ffffff);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Ui.dp(getContext(),1));c.drawCircle(getWidth()*.85f,getHeight()*.4f,getHeight()*.7f,paint);c.drawCircle(getWidth()*.85f,getHeight()*.4f,getHeight()*.44f,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0xffe7f6f0);paint.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));paint.setTextSize(Ui.dp(getContext(),30));String name=title(entry.name);c.drawText(name.isEmpty()?"PS":name.substring(0,1).toUpperCase(Locale.ROOT),Ui.dp(getContext(),14),getHeight()*.7f,paint);paint.setTextSize(Ui.dp(getContext(),8));paint.setTypeface(Typeface.DEFAULT_BOLD);paint.setColor(0xffa4c2c2);c.drawText("PLAYSTATION",Ui.dp(getContext(),14),Ui.dp(getContext(),16),paint);}}
}
